(6696561, 1000163, 53710, '<td valign="top">love how the smoke / steam transitions into the clouds, well done</td>', 'love how the smoke / steam transitions into the clouds, well done', '2012-03-01 10:29:57.000000', NULL, 1),
(6696562, 999847, 134859, '<td valign="top">I really love these winter shots.  And this photo reminds me of one particular spot in Oklahoma.  The trees were all planted by prisoners, in a perfectly straight line... so no matter where you stood in the midst of it all, you could see a straight path.  It was rumored that the woods there were haunted, though I never went there at night (what a pity).  Beautifully composed and processed.  Love the sunlight peeking through the trees.  The sharpness is right on.  And the photo is wonderful!</td>', 'I really love these winter shots.  And this photo reminds me of one particular spot in Oklahoma.  The trees were all planted by prisoners, in a perfectly straight line... so no matter where you stood in the midst of it all, you could see a straight path.  It was rumored that the woods there were haunted, though I never went there at night (what a pity).  Beautifully composed and processed.  Love the sunlight peeking through the trees.  The sharpness is right on.  And the photo is wonderful!', '2012-03-01 10:31:08.000000', NULL, 1),
(6696563, 1001280, 53710, '<td valign="top">love the color, power sky, well done</td>', 'love the color, power sky, well done', '2012-03-01 10:31:16.000000', NULL, 1),
