INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6698417, 1001471, 134859, '<td valign="top">A little noisy for me.  And there''s a reflection of red in her eyes which is throwing it off for me.  It''s a cute shot though</td>', 'A little noisy for me.  And there''s a reflection of red in her eyes which is throwing it off for me.  It''s a cute shot though', '2012-03-02 14:13:38.000000', NULL, 1),
(6698418, 1001707, 134859, '<td valign="top">Many times, the shadowing on a shot like this will take away from the image.  But here, it adds a mystery.  I like it.  Nicely done</td>', 'Many times, the shadowing on a shot like this will take away from the image.  But here, it adds a mystery.  I like it.  Nicely done', '2012-03-02 14:14:15.000000', NULL, 1),
(6698419, 1001026, 85430, '<td valign="top">Eye-candy. This image has the advantage of being cherry-picked by voters, including me. It grabs my attention in the first few seconds i see it, and my untrained eye usually falls easily for good-looking images like this.<br/> <br/>A minute passes by and I am still looking at it, giving me a chance to take note of the other elements of this image. I see that the colors are a bit unnatural, but they are pleasant colors. I would have cropped off the empty right portion as it does not add anything to the image. In fact a square crop from the top left all the way to the bottom may have worked quite well here. The position of the boats are perfect. The light, shadows and reflections were all handled well.  Overall, i like your image. Please accept my 7 for it.</td>', 'Eye-candy. This image has the advantage of being cherry-picked by voters, including me. It grabs my attention in the first few seconds i see it, and my untrained eye usually falls easily for good-looking images like this. A minute passes by and I am still looking at it, giving me a chance to take note of the other elements of this image. I see that the colors are a bit unnatural, but they are pleasant colors. I would have cropped off the empty right portion as it does not add anything to the image. In fact a square crop from the top left all the way to the bottom may have worked quite well here. The position of the boats are perfect. The light, shadows and reflections were all handled well.  Overall, i like your image. Please accept my 7 for it.', '2012-03-02 14:14:37.000000', NULL, 1),
(6698420, 1001871, 134859, '<td valign="top">Cute shot.  The lighting is a little dark on the right side of the image.  Would have liked to have seen less shadowing on her face.  But I love the black and white conversion</td>', 'Cute shot.  The lighting is a little dark on the right side of the image.  Would have liked to have seen less shadowing on her face.  But I love the black and white conversion', '2012-03-02 14:14:51.000000', NULL, 1),
