INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6699043, 1000138, 85430, '<td valign="top">Beautiful depth of field. Nicely exposed. The skin looks so natural. 6 from me.</td>', 'Beautiful depth of field. Nicely exposed. The skin looks so natural. 6 from me.', '2012-03-03 08:53:57.000000', NULL, 1),
(6699069, 1001878, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: Difficult to get your head around - of course, this is a good thing! Suggestions of sand, sea, foam, frame, face and the squiggle of your title. Some of the more abstract images feel a little flat - this maintains its depth.<br/> <br/>Critical stuff: I''m not sure about the tonality - I think I''d like a little more contrast.<br/> <br/>Overall: Interesting and bold for a Free Study</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: Difficult to get your head around - of course, this is a good thing! Suggestions of sand, sea, foam, frame, face and the squiggle of your title. Some of the more abstract images feel a little flat - this maintains its depth. Critical stuff: I''m not sure about the tonality - I think I''d like a little more contrast. Overall: Interesting and bold for a Free Study', '2012-03-03 09:59:15.000000', NULL, 1),
