(6702134, 997588, 87751, '<td valign="top">One of my absolute favorite images EVER.  Nice work!!!</td>', 'One of my absolute favorite images EVER.  Nice work!!!', '2012-03-06 23:50:40.000000', NULL, 1),
(6702135, 1001683, 97225, '<td valign="top">Beautiful shot. The rigging shows up wonderfully against the sky.</td>', 'Beautiful shot. The rigging shows up wonderfully against the sky.', '2012-03-06 23:51:25.000000', NULL, 1),
