(6702981, 1001125, 140305, '<td valign="top">Beautiful dappled light!</td>', 'Beautiful dappled light!', '2012-03-07 14:48:03.000000', NULL, 1),
(6702986, 1001803, 138630, '<td valign="top">Absolutely beautiful lighting and detail in this in-flight capture.  The natural background is lovely and I like that there is plenty of space for the hawk to fly into.  A top pick for me.</td>', 'Absolutely beautiful lighting and detail in this in-flight capture.  The natural background is lovely and I like that there is plenty of space for the hawk to fly into.  A top pick for me.', '2012-03-07 14:57:16.000000', NULL, 1),
(6702990, 1000420, 138630, '<td valign="top">Lovely colors with the frosty look to the golden grasses, the pinks in the clouds and on the mountains and the range of blues in the sky and reflection.  Clarity is excellent and I really like the composition - nice layers and the water leads the eye into the frame beautifully and I love that it ends with a glimpse of the peak in the reflection.  One of my favorites.</td>', 'Lovely colors with the frosty look to the golden grasses, the pinks in the clouds and on the mountains and the range of blues in the sky and reflection.  Clarity is excellent and I really like the composition - nice layers and the water leads the eye into the frame beautifully and I love that it ends with a glimpse of the peak in the reflection.  One of my favorites.', '2012-03-07 15:00:10.000000', NULL, 1),
(6702993, 1000582, 138630, '<td valign="top">Terrific focus, depth of field and light.  I like the composition, too, which I find slightly whimsical but nicely balanced.  Is it a bit over-sharpened around the head and over the top of the beak?  A top pick for me.</td>', 'Terrific focus, depth of field and light.  I like the composition, too, which I find slightly whimsical but nicely balanced.  Is it a bit over-sharpened around the head and over the top of the beak?  A top pick for me.', '2012-03-07 15:01:48.000000', NULL, 1),
(6702997, 1000950, 138630, '<td valign="top">A magical place and a terrific lens choice that really draws me in to the glitter and luxury.  The symmetry is almost perfect.  A personal favorite.</td>', 'A magical place and a terrific lens choice that really draws me in to the glitter and luxury.  The symmetry is almost perfect.  A personal favorite.', '2012-03-07 15:04:18.000000', NULL, 1),
(6703002, 1001026, 138630, '<td valign="top">This is quieter than some of my other top picks, but that suits the mood very well.  Especially like the rings in the water.  The compositional balance is very nice.  A favorite.</td>', 'This is quieter than some of my other top picks, but that suits the mood very well.  Especially like the rings in the water.  The compositional balance is very nice.  A favorite.', '2012-03-07 15:06:21.000000', NULL, 1),
(6703006, 1001513, 138630, '<td valign="top">Here I am drawn to the wonderful lighting and the warm expression that lets me know I would enjoy knowing this man.  Though there are some other excellent portraits, this is the only one in my top ten.</td>', 'Here I am drawn to the wonderful lighting and the warm expression that lets me know I would enjoy knowing this man.  Though there are some other excellent portraits, this is the only one in my top ten.', '2012-03-07 15:08:43.000000', NULL, 1),
(6703009, 997142, 138630, '<td valign="top">I have tried and tried to get a good aquarium shot -- never succeeded.  This is gorgeous.  The lighting, color, detail and clarity are awesome.  One of my top ten.</td>', 'I have tried and tried to get a good aquarium shot -- never succeeded.  This is gorgeous.  The lighting, color, detail and clarity are awesome.  One of my top ten.', '2012-03-07 15:11:24.000000', NULL, 1),
