(6703783, 999866, 104230, '<td valign="top">Paul, congratulations. Fascinating, evocative, great DOF and tones. I love the position of her hands and the strand of hair that has either escaped or was never captured.</td>', 'Paul, congratulations. Fascinating, evocative, great DOF and tones. I love the position of her hands and the strand of hair that has either escaped or was never captured.', '2012-03-08 00:29:58.000000', NULL, 0),
