(6703787, 1000976, 104230, '<td valign="top">Yes, I think it''s called entropy!  Congrats on a great image and finish, John.</td>', 'Yes, I think it''s called entropy!  Congrats on a great image and finish, John.', '2012-03-08 00:32:03.000000', NULL, 0),
(6703788, 1001304, 68504, '<td valign="top">Very effective composition: I see it receding upwards, as indeed it does, but also advancing viewerwards like an enormous rococo breast. And I suspect this gives me a better idea of the cupola than if I were there.</td>', 'Very effective composition: I see it receding upwards, as indeed it does, but also advancing viewerwards like an enormous rococo breast. And I suspect this gives me a better idea of the cupola than if I were there.', '2012-03-08 00:33:01.000000', NULL, 0),
(6703789, 1001820, 113591, '<td valign="top">The seeds of destruction lay strewn over barren, marred by refuse land, a lone pacifier unable to soften the ugliness.</td>', 'The seeds of destruction lay strewn over barren, marred by refuse land, a lone pacifier unable to soften the ugliness.', '2012-03-08 00:33:39.000000', NULL, 0),
(6703790, 999590, 68504, '<td valign="top">Beautiful and ominous. A great work of ambivalence.</td>', 'Beautiful and ominous. A great work of ambivalence.', '2012-03-08 00:34:31.000000', NULL, 0),
(6703791, 1001846, 108580, '<td valign="top">It pains me to see technically more difficult BiF images so far down the order...screw that! I gave it a 7 and deservedly so.<br/> <br/>Did you use AF-C and a selective Focus Point on the D90?</td>', 'It pains me to see technically more difficult BiF images so far down the order...screw that! I gave it a 7 and deservedly so. Did you use AF-C and a selective Focus Point on the D90?', '2012-03-08 00:35:00.000000', NULL, 0),
